 public Task<string> ReadLineAsync(CallOptions options = null, CancellationToken cancellationToken = default(CancellationToken)){return Start(cancellationToken,(Arena a,IntPtr h,IntPtr cancel,Native.Completion cb,IntPtr user,out IntPtr op)=>{var o=a.Options(options,cancel);return Native.cd_read_line_async(h,o,cb,user,out op);},r=>{Interop.Checked(Native.cd_result_get_status(r),r);return Interop.Response<string>(r,options==null?0:(int)options.ReadStream);});}
