 public Task WriteBytesAsync(byte[] input, CallOptions options = null, CancellationToken cancellationToken = default(CancellationToken)){return Start(cancellationToken,(Arena a,IntPtr h,IntPtr cancel,Native.Completion cb,IntPtr user,out IntPtr op)=>{var o=a.Options(options,cancel);if(input==null)throw new ArgumentNullException(nameof(input));return Native.cd_write_bytes_async(h,a.Bytes(input),o,cb,user,out op);},r=>{Interop.Checked(Native.cd_result_get_status(r),r);return true;});}
