 public void WriteLine(string input, CallOptions options = null, CancellationToken cancellationToken = default(CancellationToken)){WriteLineAsync(input, options,cancellationToken).GetAwaiter().GetResult();}
 public Task<ExecutionResult<string>> ExecuteAsync(string command, Check check = null, CallOptions options = null, CancellationToken cancellationToken = default(CancellationToken)){return Start(cancellationToken,(Arena a,IntPtr h,IntPtr cancel,Native.Completion cb,IntPtr user,out IntPtr op)=>{var o=a.Options(options,cancel);var checkPtr=check==null?IntPtr.Zero:a.Struct(a.Check(check));if(command==null)throw new ArgumentNullException(nameof(command));return Native.cd_execute_string_async(h,a.Text(command),checkPtr,o,cb,user,out op);},r=>Interop.Execution<string>(r));}
